00065 #else /* defined (HAVE_KERN_PROC_ARGS) || |defined (HAVE_KERN_PROC) */
00066 
00067 static char *
00068 sysctl_exec_name (struct backtrace_state *state,
00069           int mib0, int mib1, int mib2, int mib3,
00070           backtrace_error_callback error_callback, void *data)
00071 {
00072   int mib[4];
00073   size_t len;
00074   char *name;
00075   size_t rlen;
00076 
00077   mib[0] = mib0;
00078   mib[1] = mib1;
00079   mib[2] = mib2;
00080   mib[3] = mib3;
00081 
00082   if (sysctl (mib, 4, NULL, &len, NULL, 0) < 0)
00083     return NULL;
00084   name = (char *) backtrace_alloc (state, len, error_callback, data);
00085   if (name == NULL)
00086     return NULL;
00087   rlen = len;
00088   if (sysctl (mib, 4, name, &rlen, NULL, 0) < 0)
00089     {
00090       backtrace_free (state, name, len, error_callback, data);
00091       return NULL;
00092     }
00093   return name;
00094 }
00095 
