00134 static char *
00135 macho_get_executable_path (struct backtrace_state *state,
00136                backtrace_error_callback error_callback, void *data)
00137 {
00138   uint32_t len;
00139   char *name;
00140 
00141   len = 0;
00142   if (_NSGetExecutablePath (NULL, &len) == 0)
00143     return NULL;
00144   name = (char *) backtrace_alloc (state, len, error_callback, data);
00145   if (name == NULL)
00146     return NULL;
00147   if (_NSGetExecutablePath (name, &len) != 0)
00148     {
00149       backtrace_free (state, name, len, error_callback, data);
00150       return NULL;
00151     }
00152   return name;
00153 }
00154 
00155 #else /* !defined (HAVE_MACH_O_DYLD_H) */
00156 
00157 #define macho_get_executable_path(state, error_callback, data) NULL
00158 
00159 #endif /* !defined (HAVE_MACH_O_DYLD_H) */
