00161 /* Initialize the fileline information from the executable.  Returns 1
00162    on success, 0 on failure.  */
00163 
00164 static int
00165 fileline_initialize (struct backtrace_state *state,
00166              backtrace_error_callback error_callback, void *data)
00167 {
00168   int failed;
00169   fileline fileline_fn;
00170   int pass;
00171   int called_error_callback;
00172   int descriptor;
00173   const char *filename;
00174   char buf[64];
00175 
00176   if (!state->threaded)
00177     failed = state->fileline_initialization_failed;
00178   else
00179     failed = backtrace_atomic_load_int (&state->fileline_initialization_failed);
00180 
00181   if (failed)
00182     {
00183       error_callback (data, "failed to read executable information", -1);
00184       return 0;
00185     }
00186 
00187   if (!state->threaded)
00188     fileline_fn = state->fileline_fn;
00189   else
00190     fileline_fn = backtrace_atomic_load_pointer (&state->fileline_fn);
00191   if (fileline_fn != NULL)
00192     return 1;
00193 
00194   /* We have not initialized the information.  Do it now.  */
00195 
00196   descriptor = -1;
00197   called_error_callback = 0;
00198   for (pass = 0; pass < 8; ++pass)
00199     {
00200       int does_not_exist;
00201 
00202       switch (pass)
00203     {
00204     case 0:
00205       filename = state->filename;
00206       break;
00207     case 1:
00208       filename = getexecname ();
00209       break;
00210     case 2:
00211       filename = "/proc/self/exe";
00212       break;
00213     case 3:
00214       filename = "/proc/curproc/file";
00215       break;
00216     case 4:
00217       snprintf (buf, sizeof (buf), "/proc/%ld/object/a.out",
00218             (long) getpid ());
00219       filename = buf;
00220       break;
00221     case 5:
00222       filename = sysctl_exec_name1 (state, error_callback, data);
00223       break;
00224     case 6:
00225       filename = sysctl_exec_name2 (state, error_callback, data);
00226       break;
00227     case 7:
00228       filename = macho_get_executable_path (state, error_callback, data);
00229       break;
00230     default:
00231       abort ();
00232     }
00233 
00234       if (filename == NULL)
00235     continue;
00236 
00237       descriptor = backtrace_open (filename, error_callback, data,
00238                    &does_not_exist);
00239       if (descriptor < 0 && !does_not_exist)
00240     {
00241       called_error_callback = 1;
00242       break;
00243     }
00244       if (descriptor >= 0)
00245     break;
00246     }
00247 
00248   if (descriptor < 0)
00249     {
00250       if (!called_error_callback)
00251     {
00252       if (state->filename != NULL)
00253         error_callback (data, state->filename, ENOENT);
00254       else
00255         error_callback (data,
00256                 "libbacktrace could not find executable to open",
00257                 0);
00258     }
00259       failed = 1;
00260     }
00261 
00262   if (!failed)
00263     {
00264       if (!backtrace_initialize (state, filename, descriptor, error_callback,
00265                  data, &fileline_fn))
00266     failed = 1;
00267     }
00268 
00269   if (failed)
00270     {
00271       if (!state->threaded)
00272     state->fileline_initialization_failed = 1;
00273       else
00274     backtrace_atomic_store_int (&state->fileline_initialization_failed, 1);
00275       return 0;
00276     }
00277 
00278   if (!state->threaded)
00279     state->fileline_fn = fileline_fn;
00280   else
00281     {
00282       backtrace_atomic_store_pointer (&state->fileline_fn, fileline_fn);
00283 
00284       /* Note that if two threads initialize at once, one of the data
00285      sets may be leaked.  */
00286     }
00287 
00288   return 1;
00289 }
00290 
00291 /* Given a PC, find the file name, line number, and function name.  */
00292 
00293 int
00294 backtrace_pcinfo (struct backtrace_state *state, uintptr_t pc,
00295           backtrace_full_callback callback,
00296           backtrace_error_callback error_callback, void *data)
00297 {
00298   if (!fileline_initialize (state, error_callback, data))
00299     return 0;
00300 
00301   if (state->fileline_initialization_failed)
00302     return 0;
00303 
00304   return state->fileline_fn (state, pc, callback, error_callback, data);
00305 }
00306 
00307 /* Given a PC, find the symbol for it, and its value.  */
00308 
00309 int
00310 backtrace_syminfo (struct backtrace_state *state, uintptr_t pc,
00311            backtrace_syminfo_callback callback,
00312            backtrace_error_callback error_callback, void *data)
00313 {
00314   if (!fileline_initialize (state, error_callback, data))
00315     return 0;
00316 
00317   if (state->fileline_initialization_failed)
00318     return 0;
00319 
00320   state->syminfo_fn (state, pc, callback, error_callback, data);
00321   return 1;
00322 }
00323 
00324 /* A backtrace_syminfo_callback that can call into a
00325    backtrace_full_callback, used when we have a symbol table but no
00326    debug info.  */
00327 
00328 void
00329 backtrace_syminfo_to_full_callback (void *data, uintptr_t pc,
00330                     const char *symname,
00331                     uintptr_t symval ATTRIBUTE_UNUSED,
00332                     uintptr_t symsize ATTRIBUTE_UNUSED)
00333 {
00334   struct backtrace_call_full *bdata = (struct backtrace_call_full *) data;
00335 
00336   bdata->ret = bdata->full_callback (bdata->full_data, pc, 0, NULL, 0, symname);
00337 }
00338 
00339 /* An error callback that corresponds to
00340    backtrace_syminfo_to_full_callback.  */
00341 
00342 void
00343 backtrace_syminfo_to_full_error_callback (void *data, const char *msg,
00344                       int errnum)
00345 {
00346   struct backtrace_call_full *bdata = (struct backtrace_call_full *) data;
00347 
00348   bdata->full_error_callback (bdata->full_data, msg, errnum);
00349 }
